$repoRoot = [System.IO.Path]::GetFullPath((Get-Location).Path)
Set-Location (Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract')

if ($PSVersionTable.PSVersion -lt [version]'7.6') {
    throw "PowerShell 7.6 or newer is required; observed $($PSVersionTable.PSVersion)"
}
if (-not (Get-Command python -ErrorAction SilentlyContinue)) {
    throw 'A normal Python installation exposing the python command is required.'
}
$pythonVersionText = (& python -c "import sys; print('.'.join(map(str, sys.version_info[:3])))").Trim()
if ($LASTEXITCODE -ne 0) {
    throw "Could not run Python preflight; exit code $LASTEXITCODE"
}
$pythonVersion = [version]$pythonVersionText
if ($pythonVersion -lt [version]'3.11') {
    throw "Python 3.11 or newer is intended; observed $pythonVersionText. Only 3.13.9 is qualified for this lab."
}
Write-Host "PowerShell observed: $($PSVersionTable.PSVersion); qualified test version: 7.6.6"
Write-Host "Python observed: $pythonVersionText; qualified test version: 3.13.9"
Write-Host ".NET observed: $([System.Environment]::Version); qualified version: 10.0.12"

$requiredFiles = @(
    '.\Start-ServingLab.ps1',
    '.\Stop-ServingLab.ps1',
    '.\Invoke-ServingChild.ps1',
    '.\Serving-Time.ps1',
    '.\Setup-ServingLab.ps1',
    '.\Test-ServingLifecycle.ps1',
    '.\conformance.py',
    '.\test_conformance.py',
    '.\adapter_exercise.py',
    '.\adapter_answer.py',
    '.\test_adapter_exercise.py',
    '.\test_adapter_changed.py',
    '.\test_adapter_rollback_boundaries.py'
)
foreach ($file in $requiredFiles) {
    if (-not (Test-Path -LiteralPath $file -PathType Leaf)) {
        throw "Required supplied file is missing: $file"
    }
}

$runsParent = [System.IO.Path]::GetFullPath((Join-Path (Get-Location) 'lab-runs'))
New-Item -ItemType Directory -Path $runsParent -Force -ErrorAction Stop | Out-Null
$runRoot = Join-Path $runsParent 'serving-run-20260920-a'
if (Test-Path -LiteralPath $runRoot) {
    throw "Choose a new run name; refusing to reuse $runRoot"
}
New-Item -ItemType Directory -Path $runRoot -ErrorAction Stop | Out-Null

$workspace = Join-Path $runRoot 'workspace'
$evidence = Join-Path $runRoot 'evidence'
New-Item -ItemType Directory -Path $evidence -ErrorAction Stop | Out-Null
if (Test-Path -LiteralPath $workspace) {
    throw "Setup requires a new workspace: $workspace"
}

.\Setup-ServingLab.ps1 -Workspace $workspace
# Optional alternative for a cache containing both exact pinned files:
# .\Setup-ServingLab.ps1 -Workspace $workspace -ArtifactCache 'D:\p42-artifact-cache'

python -m unittest -v test_conformance.py
if ($LASTEXITCODE -ne 0) {
    throw "The eight synthetic client tests failed with exit code $LASTEXITCODE"
}

$receipt = Join-Path $evidence 'receipt-11842-live.json'
if (Test-Path -LiteralPath $receipt) {
    throw "Receipt already exists: $receipt"
}

$rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$keyBytes = New-Object byte[] 32
try {
    $rng.GetBytes($keyBytes)
    $env:P42_SERVING_API_KEY = [Convert]::ToBase64String($keyBytes)

    .\Start-ServingLab.ps1 -Workspace $workspace -Port 11842

    $missingKey = Invoke-WebRequest `
        -Uri 'http://127.0.0.1:11842/v1/models' `
        -Method Get `
        -SkipHttpErrorCheck `
        -TimeoutSec 10
    if ($missingKey.StatusCode -ne 401) {
        throw "Expected missing-key HTTP 401, observed $($missingKey.StatusCode)"
    }

    python conformance.py --port 11842 --output $receipt
    if ($LASTEXITCODE -ne 0) {
        throw "Live conformance failed with exit code $LASTEXITCODE"
    }
} finally {
    try {
        $statePath = Join-Path $workspace 'server-state.json'
        if (Test-Path -LiteralPath $statePath -PathType Leaf) {
            .\Stop-ServingLab.ps1 -Workspace $workspace
        }
    } finally {
        Remove-Item Env:P42_SERVING_API_KEY -ErrorAction SilentlyContinue
        if ($null -ne $keyBytes) {
            [Array]::Clear($keyBytes, 0, $keyBytes.Length)
        }
        if ($null -ne $rng) {
            $rng.Dispose()
        }
    }
}

Write-Host "Workspace: $workspace"
Write-Host "Live receipt: $receipt"

Set-Location (Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract')
if ($null -eq $workspace -or $null -eq $evidence -or $null -eq $receipt) {
    throw 'Continue in the same PowerShell session used by run-pinned-cpu-service so the persisted paths remain explicit.'
}
if (-not (Test-Path -LiteralPath $receipt -PathType Leaf)) {
    throw "Live receipt is missing: $receipt"
}

$live = Get-Content -LiteralPath $receipt -Raw | ConvertFrom-Json
$live.checks | Select-Object name, state, detail | Format-Table -Wrap
if (@($live.checks).Count -ne 12) {
    throw "Expected the qualified 12-check receipt schema; observed $(@($live.checks).Count) checks."
}

$requiredObserved = @(
    'health_public',
    'authentication_rejection',
    'server_identity',
    'bounded_completion',
    'stream',
    'early_disconnect',
    'recovery_after_disconnect',
    'overload_observation'
)
foreach ($name in $requiredObserved) {
    $check = @($live.checks | Where-Object name -eq $name)
    if ($check.Count -ne 1 -or $check[0].state -ne 'observed') {
        throw "Required live observation was not established: $name"
    }
}

$timeout = @($live.checks | Where-Object name -eq 'client_timeout')
if ($timeout.Count -ne 1) {
    throw 'The receipt must contain exactly one client_timeout check.'
}
if ($timeout[0].state -ne 'observed') {
    Write-Warning "client_timeout state is '$($timeout[0].state)'. Record this as an unmet timeout experiment, not as universal server failure."
    throw 'Required client_timeout experiment was not observed on this run.'
}

$cancellation = @($live.checks | Where-Object name -eq 'server_side_cancellation')
if ($cancellation.Count -ne 1 -or $cancellation[0].state -ne 'not-observed') {
    throw 'Do not upgrade server-side cancellation beyond the receipt evidence.'
}
foreach ($name in @('stop_restart_recovery', 'artifact_hashes')) {
    $check = @($live.checks | Where-Object name -eq $name)
    if ($check.Count -ne 1 -or $check[0].state -ne 'not-observed') {
        throw "The port-only receipt must leave separate evidence as not-observed: $name"
    }
}

$testRoot = Join-Path $evidence 'lifecycle-test-evidence'
if (Test-Path -LiteralPath $testRoot) {
    throw "Choose a new lifecycle evidence path: $testRoot"
}
New-Item -ItemType Directory -Path $testRoot -ErrorAction Stop | Out-Null

$lifecycleRng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$lifecycleKeyBytes = New-Object byte[] 32
try {
    $lifecycleRng.GetBytes($lifecycleKeyBytes)
    $env:P42_SERVING_API_KEY = [Convert]::ToBase64String($lifecycleKeyBytes)
    .\Test-ServingLifecycle.ps1 -Workspace $workspace -TestRoot $testRoot -Port 11842
} finally {
    Remove-Item Env:P42_SERVING_API_KEY -ErrorAction SilentlyContinue
    if ($null -ne $lifecycleKeyBytes) {
        [Array]::Clear($lifecycleKeyBytes, 0, $lifecycleKeyBytes.Length)
    }
    if ($null -ne $lifecycleRng) {
        $lifecycleRng.Dispose()
    }
}
Write-Host "Lifecycle evidence: $testRoot"

Set-Location (Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract')
$practice = [System.IO.Path]::GetFullPath((Join-Path (Get-Location) 'lab-runs\sse-mutation-20260920-a'))
if (Test-Path -LiteralPath $practice) {
    throw "Choose a new mutation directory: $practice"
}
New-Item -ItemType Directory -Path $practice -ErrorAction Stop | Out-Null
Copy-Item .\conformance.py (Join-Path $practice 'conformance.py') -ErrorAction Stop
Copy-Item .\test_conformance.py (Join-Path $practice 'test_conformance.py') -ErrorAction Stop
Copy-Item .\conformance.py (Join-Path $practice 'conformance.reference.py') -ErrorAction Stop
$protectedTestsHash = (Get-FileHash -LiteralPath (Join-Path $practice 'test_conformance.py') -Algorithm SHA256 -ErrorAction Stop).Hash

$mutator = @'
from pathlib import Path
p = Path("conformance.py")
data = p.read_bytes()
lf = b'    if not done:\n        raise SafeError("SSE stream ended without DONE")\n'
crlf = b'    if not done:\r\n        raise SafeError("SSE stream ended without DONE")\r\n'
count = data.count(lf) + data.count(crlf)
if count != 1:
    raise SystemExit(f"expected exactly one missing-DONE guard, found {count}")
if crlf in data:
    data = data.replace(crlf, b'', 1)
else:
    data = data.replace(lf, b'', 1)
p.write_bytes(data)
'@
Set-Content -LiteralPath (Join-Path $practice 'mutate_guard.py') -Value $mutator -Encoding utf8 -NoNewline

Push-Location $practice
try {
    $diagnosticFailure = $null
    $restorationFailure = $null

    try {
        python .\mutate_guard.py
        if ($LASTEXITCODE -ne 0) {
            throw "Mutation helper failed with exit code $LASTEXITCODE"
        }

        $mutatedOutput = & python -m unittest -v test_conformance.py 2>&1
        $mutatedExit = $LASTEXITCODE
        $mutatedOutput | ForEach-Object { Write-Host $_ }
        if ($mutatedExit -eq 0) {
            throw 'Expected the protected suite to detect the removed missing-DONE guard.'
        }

        $failurePattern = '(?m)^FAIL: [A-Za-z_][A-Za-z0-9_]* \((test_conformance\.ConformanceTests\.[A-Za-z_][A-Za-z0-9_]*)\)(?: .*)?\r?$'
        $joinedMutatedOutput = $mutatedOutput -join "`n"
        $failureMatch = [regex]::Match($joinedMutatedOutput, $failurePattern)
        if (-not $failureMatch.Success) {
            throw 'The mutant suite returned nonzero, but no protected unittest FAIL header identified the mutation.'
        }

        $protectedTestId = $failureMatch.Groups[1].Value
        if (-not $protectedTestId.StartsWith('test_conformance.ConformanceTests.', [System.StringComparison]::Ordinal)) {
            throw "Failure identifier is outside test_conformance.ConformanceTests: $protectedTestId"
        }
        Write-Host "Named protected test: $protectedTestId"

        $singleOutput = & python -m unittest -v $protectedTestId 2>&1
        $singleExit = $LASTEXITCODE
        $singleOutput | ForEach-Object { Write-Host $_ }
        if ($singleExit -eq 0) {
            throw "Expected the named protected test to fail against the mutation: $protectedTestId"
        }

        $joinedSingleOutput = $singleOutput -join "`n"
        $singleFailureMatches = [regex]::Matches($joinedSingleOutput, $failurePattern)
        $namedFailureObserved = $false
        foreach ($singleFailureMatch in $singleFailureMatches) {
            if ($singleFailureMatch.Groups[1].Value -ceq $protectedTestId) {
                $namedFailureObserved = $true
                break
            }
        }
        if (-not $namedFailureObserved) {
            throw "The named test returned nonzero without a matching unittest FAIL header: $protectedTestId"
        }
    } catch {
        $diagnosticFailure = $_
    } finally {
        try {
            Copy-Item .\conformance.reference.py .\conformance.py -Force -ErrorAction Stop
        } catch {
            $restorationFailure = $_
        }
    }

    if ($null -ne $restorationFailure) {
        throw "Could not restore conformance.py from its reference copy: $($restorationFailure.Exception.Message)"
    }

    $currentProtectedTestsHash = (Get-FileHash -LiteralPath .\test_conformance.py -Algorithm SHA256 -ErrorAction Stop).Hash
    if ($currentProtectedTestsHash -cne $protectedTestsHash) {
        throw 'Protected test_conformance.py changed during the mutation exercise.'
    }

    $recoveryOutput = & python -m unittest -v test_conformance.py 2>&1
    $recoveryExit = $LASTEXITCODE
    $recoveryOutput | ForEach-Object { Write-Host $_ }
    $joinedRecoveryOutput = $recoveryOutput -join "`n"
    $ranEight = [regex]::IsMatch($joinedRecoveryOutput, '(?m)^Ran 8 tests in [0-9.]+s\r?$')
    if ($recoveryExit -ne 0 -or -not $ranEight) {
        $diagnosticContext = if ($null -ne $diagnosticFailure) { " Earlier mutation diagnosis error: $($diagnosticFailure.Exception.Message)" } else { '' }
        throw "The unchanged eight-test protected suite did not pass after restoration; exit code $recoveryExit.$diagnosticContext"
    }

    if ($null -ne $diagnosticFailure) {
        throw "Mutation diagnosis failed, although restoration and the eight-test recovery succeeded: $($diagnosticFailure.Exception.Message)"
    }
} finally {
    Pop-Location
}
Write-Host "Preserved mutation evidence: $practice"

Set-Location (Join-Path $repoRoot 'modules/self-hosted-model-operations/lab/serving-contract')
$runsParent = [System.IO.Path]::GetFullPath((Join-Path (Get-Location) 'lab-runs'))
$runRoot = Join-Path $runsParent 'serving-run-20260920-a'
$workspace = Join-Path $runRoot 'workspace'
$evidence = Join-Path $runRoot 'evidence'
if (-not (Test-Path -LiteralPath $workspace -PathType Container)) {
    throw "Verified baseline workspace is missing: $workspace"
}
if (-not (Test-Path -LiteralPath $evidence -PathType Container)) {
    throw "Baseline evidence directory is missing: $evidence"
}

$statePath = Join-Path $workspace 'server-state.json'
if (Test-Path -LiteralPath $statePath -PathType Leaf) {
    .\Stop-ServingLab.ps1 -Workspace $workspace
}

$oldClient = [System.Net.Sockets.TcpClient]::new()
$oldPortRefused = $false
try {
    $oldAttempt = $oldClient.ConnectAsync('127.0.0.1', 11842)
    try {
        $completed = $oldAttempt.Wait(5000)
    } catch {
        $baseEx = $_.Exception.GetBaseException()
        if ($baseEx -is [System.Net.Sockets.SocketException] -and
            $baseEx.SocketErrorCode -eq [System.Net.Sockets.SocketError]::ConnectionRefused) {
            $oldPortRefused = $true
        } else {
            throw
        }
    }

    if (-not $oldPortRefused) {
        if (-not $completed) {
            throw 'Old-port connection attempt exceeded 5000 ms; timeout is not proof that the port is closed.'
        }
        if ($oldClient.Connected -or $oldAttempt.Status -eq [System.Threading.Tasks.TaskStatus]::RanToCompletion) {
            throw 'Old port 11842 accepted a connection after the owned stop.'
        }
        if ($oldAttempt.IsFaulted) {
            $baseEx = $oldAttempt.Exception.GetBaseException()
            if ($baseEx -is [System.Net.Sockets.SocketException] -and
                $baseEx.SocketErrorCode -eq [System.Net.Sockets.SocketError]::ConnectionRefused) {
                $oldPortRefused = $true
            } else {
                throw $oldAttempt.Exception
            }
        }
    }
    if (-not $oldPortRefused) {
        throw 'Old-port closure was not proven by SocketError.ConnectionRefused.'
    }
} finally {
    $oldClient.Dispose()
}
Write-Host 'Old port 11842 was closed with SocketError.ConnectionRefused.'

$port = 11901
$receipt11901 = Join-Path $evidence 'receipt-11901-live.json'
if (Test-Path -LiteralPath $receipt11901) {
    throw "Receipt already exists: $receipt11901"
}

$rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
$keyBytes = New-Object byte[] 32
try {
    $rng.GetBytes($keyBytes)
    $env:P42_SERVING_API_KEY = [Convert]::ToBase64String($keyBytes)

    .\Start-ServingLab.ps1 -Workspace $workspace -Port $port
    python conformance.py --port $port --output $receipt11901
    if ($LASTEXITCODE -ne 0) {
        throw "Changed-port conformance failed with exit code $LASTEXITCODE"
    }

    $changed = Get-Content -LiteralPath $receipt11901 -Raw | ConvertFrom-Json
    if ($changed.port -ne 11901) {
        throw "Changed receipt recorded unexpected port: $($changed.port)"
    }
    if (@($changed.checks).Count -ne 12) {
        throw "Expected the qualified 12-check receipt schema; observed $(@($changed.checks).Count) checks."
    }
    $requiredChangedObserved = @(
        'health_public',
        'authentication_rejection',
        'server_identity',
        'bounded_completion',
        'stream',
        'early_disconnect',
        'recovery_after_disconnect',
        'overload_observation'
    )
    foreach ($name in $requiredChangedObserved) {
        $check = @($changed.checks | Where-Object name -eq $name)
        if ($check.Count -ne 1 -or $check[0].state -ne 'observed') {
            throw "Changed-port required observation was not established: $name"
        }
    }
    $identity = @($changed.checks | Where-Object name -eq 'server_identity')
    if ($identity[0].alias -ne 'p42-qwen3-06b') {
        throw 'Changed-port authenticated identity did not contain the required alias.'
    }
    $changedTimeout = @($changed.checks | Where-Object name -eq 'client_timeout')
    if ($changedTimeout.Count -ne 1) {
        throw 'Changed-port receipt must contain exactly one client_timeout check.'
    }
    if ($changedTimeout[0].state -ne 'observed') {
        Write-Warning "Changed-port client_timeout state is '$($changedTimeout[0].state)'. Record it as an unmet experiment, not universal server failure."
        throw 'Changed-port client_timeout experiment was not observed.'
    }
    $changedCancellation = @($changed.checks | Where-Object name -eq 'server_side_cancellation')
    if ($changedCancellation.Count -ne 1 -or $changedCancellation[0].state -ne 'not-observed') {
        throw 'Do not upgrade changed-port server-side cancellation beyond the receipt evidence.'
    }
} finally {
    try {
        if (Test-Path -LiteralPath $statePath -PathType Leaf) {
            .\Stop-ServingLab.ps1 -Workspace $workspace
        }
    } finally {
        Remove-Item Env:P42_SERVING_API_KEY -ErrorAction SilentlyContinue
        if ($null -ne $keyBytes) {
            [Array]::Clear($keyBytes, 0, $keyBytes.Length)
        }
        if ($null -ne $rng) {
            $rng.Dispose()
        }
    }
}
Write-Host "Changed-port receipt: $receipt11901"
Write-Host 'The server is stopped; preserve setup, lifecycle, receipt, and stop evidence separately.'
